package com.sigtm.backend.controller; import com.sigtm.backend.model.InspeccionRecepcionCompra; import com.sigtm.backend.service.InspeccionRecepcionCompraService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/recepciones/{receiptId}/inspecciones") @RequiredArgsConstructor public class InspeccionRecepcionCompraController {private final InspeccionRecepcionCompraService service; @GetMapping @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<InspeccionRecepcionCompra>> listar(@PathVariable Long receiptId){return ResponseEntity.ok(service.listar(receiptId));} @PostMapping("/producto/{productId}") @PreAuthorize("hasAuthority('COMPRAS:RECEPCIONAR')") public ResponseEntity<InspeccionRecepcionCompra> registrar(@PathVariable Long receiptId,@PathVariable Long productId,@RequestBody InspeccionRecepcionCompra data){return ResponseEntity.ok(service.registrar(receiptId,productId,data));}}
